exploreUrl:
@js:
var base = "https://www.gushizu.com";
var out = [];
function push(t, u, w) {
  out.push({
    title: t,
    url: u,
    style: { layout_flexGrow: 1, layout_flexBasisPercent: w || 0.25 }
  });
}
push("🏆 排行榜", "", 1);
push("点击榜", base + "/rank/allvisit", 0.25);
push("收藏榜", base + "/rank/mark", 0.25);
push("推荐榜", base + "/rank/vote", 0.25);
push("周榜", base + "/rank/weekvisit", 0.25);
push("月榜", base + "/rank/monthvisit", 0.25);
push("📚 分类", "", 1);
var cats = [
  ["科幻", 41], ["名著", 40], ["推理", 39], ["短篇", 32],
  ["中篇", 34], ["少儿版", 33], ["历史版", 8], ["国外版", 27],
  ["睡前故事", 11], ["科幻世界", 30], ["当代", 14], ["啄木鸟", 13],
  ["意林", 12], ["小说月报", 10], ["上海故事", 9], ["读者", 6],
  ["今古传奇", 5], ["故事会", 3], ["历史故事", 42]
];
for (var i = 0; i < cats.length; i++) {
  push(cats[i][0], base + "/novel/category/list/categoryId/" + cats[i][1] + "/<,page/{{page}}>", 0.25);
}
JSON.stringify(out);

ruleBookInfo.intro:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var name = doc.select('.book-title').text();
var author = doc.select('.book-intro .flex-item p:contains(作者)').text().replace('作者：','').trim();
var kind = doc.select('.book-intro .flex-item p:contains(分类)').text().replace('分类：','').trim();
var intro = doc.select('.book-intro-con p').text().trim();
var lines = [];
if(name)   lines.push('<div>　　<b>📖 书名：</b>' + name + '</div>');
if(author) lines.push('<div>　　<b>👤 作者：</b>' + author + '</div>');
if(kind)   lines.push('<div>　　<b>📂 分类：</b>' + kind + '</div>');
if(intro)  lines.push('<div>　　<b>📝 简介：</b></div><div>　　' + intro + '</div>');
lines.join('');
